#!/bin/zsh
# Point the Android release build at the real upload keystore.
#
# `android/` is generated by `expo prebuild` and is gitignored, so Expo's default
# build.gradle signs release with the DEBUG key, which Play rejects. Re-run this
# after every prebuild. The password lives in the macOS Keychain, never on disk
# in this repo: android/gradle.properties is gitignored along with android/.
set -e
HERE=${0:A:h}/..
KS="$HOME/keys/padhai/padhai-upload.jks"
ALIAS="padhai-upload"
GRADLE_PROPS="$HERE/android/gradle.properties"
BUILD_GRADLE="$HERE/android/app/build.gradle"

[ -f "$KS" ] || { echo "!! keystore missing: $KS"; exit 1; }
[ -f "$BUILD_GRADLE" ] || { echo "!! no android/ -- run: npx expo prebuild -p android"; exit 1; }
# prebuild does not write local.properties, and gradle needs the SDK path
SDK_DIR="${ANDROID_HOME:-$HOME/Library/Android/sdk}"
if [ -d "$SDK_DIR" ] && ! grep -qs "^sdk.dir=" "$HERE/android/local.properties" 2>/dev/null; then
  echo "sdk.dir=$SDK_DIR" >> "$HERE/android/local.properties"
  echo "wrote android/local.properties -> $SDK_DIR"
fi

PW=$(security find-generic-password -a "$ALIAS" -s padhai-upload-keystore -w) || {
  echo "!! keystore password not in Keychain (service padhai-upload-keystore)"; exit 1; }

sed -i '' '/^PADHAI_UPLOAD_/d' "$GRADLE_PROPS"
# prebuild leaves the file without a trailing newline, which would glue the
# first property onto the last line
[ -n "$(tail -c1 "$GRADLE_PROPS")" ] && echo "" >> "$GRADLE_PROPS"
cat >> "$GRADLE_PROPS" <<PROPS
PADHAI_UPLOAD_STORE_FILE=$KS
PADHAI_UPLOAD_STORE_PASSWORD=$PW
PADHAI_UPLOAD_KEY_ALIAS=$ALIAS
PADHAI_UPLOAD_KEY_PASSWORD=$PW
PROPS

if ! grep -q "padhaiUpload" "$BUILD_GRADLE"; then
  python3 -I - "$BUILD_GRADLE" <<'PY'
import sys, re
p = sys.argv[1]
s = open(p).read()
block = """        padhaiUpload {
            storeFile file(project.property('PADHAI_UPLOAD_STORE_FILE'))
            storePassword project.property('PADHAI_UPLOAD_STORE_PASSWORD')
            keyAlias project.property('PADHAI_UPLOAD_KEY_ALIAS')
            keyPassword project.property('PADHAI_UPLOAD_KEY_PASSWORD')
        }
"""
s = re.sub(r"(    signingConfigs \{\n)", r"\1" + block, s, count=1)
s, n = re.subn(r"(        release \{\n(?:\s*//[^\n]*\n)*\s*)signingConfig signingConfigs\.debug", r"\1signingConfig signingConfigs.padhaiUpload", s, count=1)
if n != 1:
    sys.exit("could not find the release signingConfig")
open(p, "w").write(s)
PY
fi
grep -q "signingConfig signingConfigs.padhaiUpload" "$BUILD_GRADLE" \
  && echo "release signs with the upload keystore" \
  || { echo "!! could not rewire the release signingConfig -- check $BUILD_GRADLE"; exit 1; }
